  // client/src/content/lazyResource.ts
  init_define_import_meta_env();
  function cacheBustedUrl(url, attempt) {
    if (attempt <= 0) return url;
    return `${url}${url.includes("?") ? "&" : "?"}retry=${attempt}`;
  }
  async function fetchJsonResource(url, attempt) {
    const response = await fetch(cacheBustedUrl(url, attempt), { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error(`Ressource indisponible (${response.status}).`);
    }
    return response.json();
  }
  function createRecoverableLazyLoader(importer) {
    let promise = null;
    let attempt = 0;
    return () => {
      if (!promise) {
        promise = importer(attempt).catch((error) => {
          promise = null;
          attempt += 1;
          throw error;
        });
      }
      return promise;
    };
  }

